import re,subprocess,os,collections

decls=[]
for root,dirs,files in os.walk('internal'):
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            p=os.path.join(root,f)
            for i,line in enumerate(open(p),1):
                m=re.match(r'func (\((\w+) \*?([\w\[\]]+)\) )?(\w+)\(',line)
                if m:
                    decls.append((p,i,m.group(4),bool(m.group(1))))

# gather all non-test go files
gofiles=[]
for root,dirs,files in os.walk('.'):
    if any(s in root for s in ('/.git','/web','/node_modules')): continue
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            gofiles.append(os.path.join(root,f))

src={p:open(p,errors='ignore').read().split('\n') for p in gofiles}

results=[]
for p,i,name,ismethod in decls:
    if name in ('init','main'): continue
    pat=re.compile((r'\.'if ismethod else r'\b')+re.escape(name)+r'\s*\(')
    count=0
    for f,lines in src.items():
        for ln,line in enumerate(lines,1):
            if f==p and ln==i: continue
            if line.strip().startswith('//'): continue
            if pat.search(line):
                count+=1
    results.append((count,name,p,i,ismethod))

results.sort(reverse=True)
for c,name,p,i,m in results[:25]:
    print(c,name,f"{p}:{i}","method" if m else "func")
EOF

